CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tenants (id uuid PRIMARY KEY, name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Qyzylorda', settings jsonb NOT NULL DEFAULT '{}');
CREATE TABLE organizations (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), name text NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE profiles (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), email text UNIQUE NOT NULL, name text NOT NULL, password_hash text, roles text[] NOT NULL DEFAULT '{observer}', active boolean NOT NULL DEFAULT true, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles (id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE user_roles (user_id uuid REFERENCES profiles(id), role_id text REFERENCES roles(id), PRIMARY KEY(user_id,role_id));
CREATE TABLE sessions (id text PRIMARY KEY, user_id uuid NOT NULL REFERENCES profiles(id), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE login_attempts (key text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, reset_at timestamptz NOT NULL);
CREATE TABLE teams (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), name text NOT NULL, data jsonb NOT NULL DEFAULT '{}');
CREATE TABLE team_members (team_id uuid REFERENCES teams(id), user_id uuid REFERENCES profiles(id), PRIMARY KEY(team_id,user_id));
CREATE TABLE asset_types (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), name text NOT NULL, data jsonb NOT NULL DEFAULT '{}', UNIQUE(tenant_id,name));
CREATE TABLE assets (
 id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), number text NOT NULL, name text NOT NULL,
 type text NOT NULL, address text NOT NULL, city text NOT NULL, district text NOT NULL,
 latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180),
 owner_id uuid NOT NULL REFERENCES organizations(id), service_id uuid NOT NULL REFERENCES organizations(id), responsible_id uuid NOT NULL REFERENCES profiles(id),
 card_status text NOT NULL DEFAULT 'draft' CHECK(card_status IN ('draft','pending','approved','returned','archived')),
 lifecycle text NOT NULL DEFAULT 'planned' CHECK(lifecycle IN ('planned','installed','operating','suspended','dismantled')),
 version integer NOT NULL DEFAULT 1, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,number));
CREATE INDEX assets_geo ON assets(latitude,longitude);
CREATE INDEX assets_filter ON assets(tenant_id,card_status,lifecycle,district,type);
CREATE TABLE asset_surfaces (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), asset_id uuid NOT NULL REFERENCES assets(id), name text NOT NULL, data jsonb NOT NULL DEFAULT '{}', UNIQUE(asset_id,name));
CREATE TABLE asset_location_history (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), asset_id uuid NOT NULL REFERENCES assets(id), data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE asset_responsibilities (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), asset_id uuid NOT NULL REFERENCES assets(id), user_id uuid NOT NULL REFERENCES profiles(id), data jsonb NOT NULL DEFAULT '{}');
CREATE TABLE attachments (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), asset_id uuid REFERENCES assets(id), uploaded_by uuid NOT NULL REFERENCES profiles(id), name text NOT NULL, mime text NOT NULL, size integer NOT NULL CHECK(size>0 AND size<=10485760), storage_key text NOT NULL UNIQUE, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE asset_photos (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), asset_id uuid NOT NULL REFERENCES assets(id), attachment_id uuid NOT NULL REFERENCES attachments(id), data jsonb NOT NULL DEFAULT '{}');
CREATE TABLE document_types (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), name text NOT NULL, data jsonb NOT NULL DEFAULT '{}');
CREATE TABLE document_requirements (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), asset_type text NOT NULL, document_type text NOT NULL, data jsonb NOT NULL DEFAULT '{}', UNIQUE(tenant_id,asset_type,document_type));
CREATE TABLE asset_documents (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), asset_id uuid NOT NULL REFERENCES assets(id), type text NOT NULL, name text NOT NULL, number text NOT NULL, attachment_id uuid NOT NULL REFERENCES attachments(id), expires_at timestamptz, review_status text NOT NULL DEFAULT 'pending' CHECK(review_status IN ('pending','verified','returned')), version integer NOT NULL DEFAULT 1, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE document_versions (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), document_id uuid NOT NULL REFERENCES asset_documents(id), previous_id uuid REFERENCES asset_documents(id), data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inspection_template_versions (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), name text NOT NULL, version integer NOT NULL DEFAULT 1, data jsonb NOT NULL DEFAULT '{}', UNIQUE(tenant_id,name,version));
CREATE TABLE inspection_template_items (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), template_id uuid NOT NULL REFERENCES inspection_template_versions(id), name text NOT NULL, position integer NOT NULL, data jsonb NOT NULL DEFAULT '{}');
CREATE TABLE inspection_plans (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), asset_id uuid NOT NULL REFERENCES assets(id), template_id uuid NOT NULL REFERENCES inspection_template_versions(id), assignee_id uuid NOT NULL REFERENCES profiles(id), interval_days integer NOT NULL CHECK(interval_days>0), rule text NOT NULL DEFAULT 'completion' CHECK(rule IN ('completion','fixed')), next_due timestamptz NOT NULL, active boolean NOT NULL DEFAULT true, data jsonb NOT NULL DEFAULT '{}', UNIQUE(asset_id,template_id));
CREATE TABLE inspections (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), asset_id uuid NOT NULL REFERENCES assets(id), plan_id uuid REFERENCES inspection_plans(id), template_id uuid NOT NULL REFERENCES inspection_template_versions(id), assignee_id uuid NOT NULL REFERENCES profiles(id), due_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','completed','cancelled')), completed_at timestamptz, version integer NOT NULL DEFAULT 1, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(plan_id,due_at));
CREATE INDEX inspections_due ON inspections(tenant_id,status,due_at);
CREATE TABLE inspection_results (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), inspection_id uuid NOT NULL REFERENCES inspections(id), item_id uuid NOT NULL REFERENCES inspection_template_items(id), result text NOT NULL CHECK(result IN ('ok','issue','unverified','na')), data jsonb NOT NULL DEFAULT '{}', UNIQUE(inspection_id,item_id));
CREATE TABLE defects (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), asset_id uuid NOT NULL REFERENCES assets(id), surface_id uuid REFERENCES asset_surfaces(id), inspection_id uuid REFERENCES inspections(id), author_id uuid NOT NULL REFERENCES profiles(id), description text NOT NULL, category text NOT NULL, severity text NOT NULL CHECK(severity IN ('minor','repair','critical')), priority text, status text NOT NULL DEFAULT 'registered' CHECK(status IN ('registered','review','confirmed','in_progress','verification','closed','rejected','duplicate')), version integer NOT NULL DEFAULT 1, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz);
CREATE INDEX defects_active ON defects(asset_id,status,severity);
CREATE TABLE defect_attachments (defect_id uuid REFERENCES defects(id), attachment_id uuid REFERENCES attachments(id), PRIMARY KEY(defect_id,attachment_id));
CREATE TABLE work_orders (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), asset_id uuid NOT NULL REFERENCES assets(id), title text NOT NULL, description text NOT NULL, type text NOT NULL, priority text NOT NULL, assignee_id uuid NOT NULL REFERENCES profiles(id), team_id uuid REFERENCES teams(id), due_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'assigned' CHECK(status IN ('draft','assigned','accepted','in_progress','paused','review','completed','rework','cancelled')), version integer NOT NULL DEFAULT 1, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE INDEX work_orders_due ON work_orders(tenant_id,status,due_at);
CREATE TABLE work_order_defects (work_id uuid REFERENCES work_orders(id), defect_id uuid REFERENCES defects(id), resolved boolean NOT NULL DEFAULT false, PRIMARY KEY(work_id,defect_id));
CREATE TABLE work_order_assignments (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), work_id uuid NOT NULL REFERENCES work_orders(id), user_id uuid NOT NULL REFERENCES profiles(id), data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE work_logs (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), work_id uuid NOT NULL REFERENCES work_orders(id), author_id uuid NOT NULL REFERENCES profiles(id), data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE work_materials (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), work_id uuid NOT NULL REFERENCES work_orders(id), name text NOT NULL, quantity numeric(14,3) NOT NULL CHECK(quantity>=0), unit text NOT NULL, cost numeric(16,2) NOT NULL CHECK(cost>=0), data jsonb NOT NULL DEFAULT '{}');
CREATE TABLE work_reviews (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), work_id uuid NOT NULL REFERENCES work_orders(id), reviewer_id uuid NOT NULL REFERENCES profiles(id), outcome text NOT NULL CHECK(outcome IN ('accepted','returned')), data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), user_id uuid NOT NULL REFERENCES profiles(id), event_key text NOT NULL, title text NOT NULL, read_at timestamptz, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,event_key));
CREATE TABLE notification_deliveries (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), notification_id uuid NOT NULL REFERENCES notifications(id), channel text NOT NULL, status text NOT NULL, data jsonb NOT NULL DEFAULT '{}', UNIQUE(notification_id,channel));
CREATE TABLE status_history (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), asset_id uuid REFERENCES assets(id), actor_id uuid REFERENCES profiles(id), entity_type text NOT NULL, entity_id uuid NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), actor_id uuid REFERENCES profiles(id), action text NOT NULL, entity_id uuid, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_keys (tenant_id uuid NOT NULL REFERENCES tenants(id), actor_id uuid NOT NULL REFERENCES profiles(id), key text NOT NULL, request_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,actor_id,key));
CREATE INDEX history_asset ON status_history(asset_id,created_at DESC);
CREATE INDEX audit_time ON audit_logs(tenant_id,created_at DESC);
